from cyclopts import App
from cyclopts.types import ExistingFile

app = App()


@app.command
def convert(input_file: ExistingFile, output_name: str) -> None:
    """Convert input_file and write the result under output_name."""
    print(f"Converting {input_file} -> {output_name}")


if __name__ == "__main__":
    app()
